def _make_stub_module( name ):
  mod = types.ModuleType( name )
  for n in _STUB_CLASS_NAMES:
    setattr( mod, n, _StubClass )
  def _getattr( attr ):
    # Dunder lookups (e.g. "__all__" during "from stub import *") must raise
    # AttributeError so star-imports fall back to the module dict keys above.
    if attr.startswith( "__" ) and attr.endswith( "__" ):
      raise AttributeError( "stub module %r has no attribute %r" % ( name, attr ) )
    return _StubCallable()
  # PEP 562: any other attribute access on the stub returns a permissive stub
  mod.__getattr__ = _getattr
  return mod

class _StubCallable:
  """Maximally permissive stand-in object (callable, indexable, attribute-y)."""
  def __init__( self, *args, **kwargs ): pass
  def __call__( self, *args, **kwargs ): return _StubCallable()
  def __getattr__( self, name ): return _StubCallable()
  def __getitem__( self, key ): return _StubCallable()
  def __iter__( self ): return iter(())
  def __repr__( self ): return "<stub>"

def _make_stub_class():
  """Fresh permissive class per name (distinct classes avoid 'duplicate base
  class' errors when two stubbed names are used as bases of one class)."""
  class _StubClass:
    def __init__( self, *args, **kwargs ): pass
    def __call__( self, *args, **kwargs ): return _StubCallable()
    def __getitem__( self, key ): return _StubCallable()
    def __iter__( self ): return iter(())
    def __repr__( self ): return "<stub-class>"
